const payload = $json.body || $json.input || $json;
const input = payload.input || payload;
const raw = String(input.text || payload.text || payload.content || '').trim();
const maxBullets = Math.max(3, Math.min(Number(input.max_bullets || payload.max_bullets || 6), 10));
const maxChars = Math.max(280, Math.min(Number(input.max_chars || payload.max_chars || 1200), 2200));
const cleaned = raw.replace(/\s+/g, ' ').trim();
const hasArabic = /[\u0600-\u06ff]/.test(cleaned);
const language = hasArabic ? 'ar' : 'en';
const splitPattern = /(?<=[.!?؟])\s+/;
const sentences = cleaned.split(splitPattern).map((s) => s.trim()).filter(Boolean);
const candidates = sentences.length ? sentences : cleaned.split(/[,;،؛]\s+/).map((s) => s.trim()).filter(Boolean);
function uniqueLimited(items, limit = 5) {
  const out = [];
  const seen = new Set();
  for (const item of items) {
    const value = String(item || '').trim();
    const normalized = value.toLowerCase().replace(/[^a-z0-9\u0600-\u06ff]+/g, ' ').trim();
    if (!normalized || seen.has(normalized)) continue;
    seen.add(normalized);
    out.push(value.length > 220 ? value.slice(0, 217).trim() + '...' : value);
    if (out.length >= limit) break;
  }
  return out;
}
const decisionRe = /(decision|decided|agreed|approved|keep|use|recommend|default|قرر|اتفق|القرار|اعتماد|نوصي|استخدم)/i;
const blockerRe = /(blocker|blocked|issue|problem|risk|cannot|can't|weak|missing|fail|ضعف|مشكلة|عائق|خطر|لا يمكن|ناقص|فشل)/i;
const actionRe = /(next|todo|action|should|add|collect|run|compare|monitor|improve|restore|backup|المطلوب|الخطوة|التالي|أضف|شغل|قارن|راقب|حسن|سيتم|سن)/i;
const decisions = uniqueLimited(candidates.filter((s) => decisionRe.test(s)), 5);
const blockers = uniqueLimited(candidates.filter((s) => blockerRe.test(s)), 5);
const next_actions = uniqueLimited(candidates.filter((s) => actionRe.test(s)), 6);
const bullets = uniqueLimited([...decisions, ...blockers, ...next_actions, ...candidates], maxBullets);
let summaryParts = [];
if (decisions.length) summaryParts.push(decisions[0]);
if (blockers.length) summaryParts.push(blockers[0]);
if (next_actions.length) summaryParts.push(next_actions[0]);
if (!summaryParts.length) summaryParts = bullets.slice(0, 3);
let summary = uniqueLimited(summaryParts, 4).join(' ');
if (!summary && cleaned) summary = cleaned.slice(0, maxChars);
if (summary.length > maxChars) summary = summary.slice(0, maxChars - 3).trim() + '...';
return [{ json: { summary, bullets, decisions, blockers, next_actions, language, source: 'n8n_summary_experiment_v2', method: 'deterministic_structured_extractive', input_length: raw.length, bullet_count: bullets.length, experimental: true } }];
